import React, { useEffect, useRef, useState } from "react";
import { Dialog, DialogContent, IconButton, Slide, Stack, Typography, } from "@mui/material";
import { ZegoExpressEngine } from "zego-express-engine-webrtc";
import { useDispatch, useSelector } from "react-redux";
import axiosInstance from "../../../utils/axios";
import webSocketService from "../../../webSocketService";
import { ResetVideoCallQueue, UpdateCallStatus } from "../../../redux/slices/videoCall";
import { PhoneX } from "phosphor-react";

const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const CallDialog = ({ open, handleClose }) => {

  const user_id = window.localStorage.getItem("user_id");
  const dispatch = useDispatch();
  const audioStreamRef = useRef(null);
  const videoStreamRef = useRef(null);
  const subscriptions = [];
  const [call_details] = useSelector((state) => state.videoCall.call_queue);
  const { incoming, status } = useSelector((state) => state.videoCall);
  const { token } = useSelector((state) => state.auth);
  const appID = 668945713;
  const server = "wss://webliveroom668945713-api-bak.coolzcloud.com/ws";
  const [userBusy, setUserBusy] = useState(false);
  const roomID = call_details?.roomID;
  const userID = call_details?.userID;
  const userName = call_details?.userName;
  // Step 1
  const zg = new ZegoExpressEngine(appID, server);
  zg.setLogConfig({ logLevel: "disable", logURL: "" });


  const audioStreamID = `audio_${call_details?.streamID}`;
  const videoStreamID = `video_${call_details?.streamID}`;


  const handleDisconnect = (event, reason) => {
    if (reason && reason === "backdropClick") {
      return;
    } else {
      webSocketService.sendMessage("/app/end_video_call", JSON.stringify({ ...call_details }));

      if (audioStreamRef.current) {
        const audioTracks = audioStreamRef.current.getTracks();
        audioTracks.forEach((track) => track.stop());
      }

      if (videoStreamRef.current) {
        const videoTracks = videoStreamRef.current.getTracks();
        videoTracks.forEach((track) => track.stop());
      }

      zg.stopPublishingStream(audioStreamID);
      zg.stopPublishingStream(videoStreamID);
      zg.stopPlayingStream(`audio_${userID}`);
      zg.stopPlayingStream(`video_${userID}`);
      zg.destroyStream(audioStreamRef.current);
      zg.destroyStream(videoStreamRef.current);
      zg.logoutRoom(roomID);

      dispatch(ResetVideoCallQueue());
      dispatch(UpdateCallStatus({ status: "" }));
      handleClose();
    }
  };

  useEffect(() => {

    if (!incoming) {
      webSocketService.sendMessage("/app/start_video_call", JSON.stringify({
        to: call_details?.streamID,
        from: userID,
        roomID,
      }));
    }

    // const timer = setTimeout(() => {
    //     webSocketService.sendMessage("/app/video_call_not_picked", JSON.stringify({ to: call_details?.streamID, from: userID }));
    // }, 30 * 1000);

    const end_video_call = webSocketService.subscribe(`/user/${user_id}/topic/end_video_call`, (data) => {
      dispatch(UpdateCallStatus({ status: "" }));
      handleDisconnect();
    });
    subscriptions.push(end_video_call);

    const video_call_missed = webSocketService.subscribe(`/user/${user_id}/topic/video_call_missed`, (data) => {
      handleDisconnect();
    });
    subscriptions.push(video_call_missed);

    const video_call_accepted = webSocketService.subscribe(`/user/${user_id}/topic/video_call_accepted`, (data) => {
      dispatch(UpdateCallStatus({ status: "ONGOING" }));
      // clearTimeout(timer);
    });
    subscriptions.push(video_call_accepted);

    const video_call_denied = webSocketService.subscribe(`/user/${user_id}/topic/video_call_denied`, (data) => {
      dispatch(UpdateCallStatus({ status: "" }));
      handleDisconnect();
    });
    subscriptions.push(video_call_denied);

    const on_another_audio_call = webSocketService.subscribe(`/user/${user_id}/topic/on_another_audio_call`, (data) => {
      setUserBusy(true);
    });
    subscriptions.push(on_another_audio_call);

    let this_token;
    async function fetchToken() {
      const response = await axiosInstance.post("/user/generate-zego-token", {
        userId: userID,
        room_id: roomID,
      }, {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
      });
      // console.log(response, "TOKEN RESPONSE");
      this_token = response.data.token.data;
    }
    fetchToken();

    // Step 2 => Check browser compatibility

    zg.checkSystemRequirements()
      .then((result) => {
        // The [result] indicates whether it is compatible. It indicates WebRTC is supported when the [webRTC] is [true]. For more results, see the API documents.

        // {
        //   webRTC: true,
        //   customCapture: true,
        //   camera: true,
        //   microphone: true,
        //   videoCodec: { H264: true, H265: false, VP8: true, VP9: true },
        //   screenSharing: true,
        //   errInfo: {}
        // }
        // console.log(result);

        const { webRTC, microphone, camera } = result;

        if (webRTC && microphone && camera) {
          zg.loginRoom(roomID, this_token, { userID, userName }, { userUpdate: true })
            .then(async (result) => {
              // console.log(result);

              // After calling the CreateStream method, you need to wait for the ZEGOCLOUD server to return the local stream object before any further operation.
              const localAudioStream = await zg.createStream({ camera: { audio: true, video: false }, });
              const localVideoStream = await zg.createStream({ camera: { audio: false, video: true }, });

              audioStreamRef.current = localAudioStream;
              videoStreamRef.current = localVideoStream;

              // Get the audio tag.
              const localAudio = document.getElementById("local-audio");
              const localVideo = document.getElementById("local-video");
              // The local stream is a MediaStream object. You can render audio by assigning the local stream to the srcObject property of video or audio.
              localAudio.srcObject = localAudioStream;
              localVideo.srcObject = localVideoStream;

              localVideo.play();

              // localStream is the MediaStream object created by calling creatStream in the previous step.
              zg.startPublishingStream(audioStreamID, localAudioStream);
              zg.startPublishingStream(videoStreamID, localVideoStream);

              zg.on("publisherStateUpdate", (result) => {
                // Callback for updates on stream publishing status.
                // ...
                // console.log(result);
                // * we can use this info to show connection status
              });

              zg.on("publishQualityUpdate", (streamID, stats) => {
                // Callback for reporting stream publishing quality.
                // ...
                // console.log(streamID, stats);
                // * we can use this info to show local audio stream quality
              });
            })
            .catch((error) => {
              // console.log(error);
            });

          // Callback for updates on the current user's room connection status.
          zg.on("roomStateUpdate", (roomID, state, errorCode, extendedData) => {
            if (state === "DISCONNECTED") {
              // Disconnected from the room
              // * Can be used to show disconnected status for a user (especially useful in a group call)
            }

            if (state === "CONNECTING") {
              // Connecting to the room
              // * Can be used to show connecting status for a user (especially useful in a group call)
            }

            if (state === "CONNECTED") {
              // Connected to the room
              // * Can be used to show connected status for a user (especially useful in a group call)
            }
          });

          // Callback for updates on the status of ther users in the room.
          zg.on("roomUserUpdate", async (roomID, updateType, userList) => {
            // console.warn(
            //   `roomUserUpdate: room ${roomID}, user ${updateType === "ADD" ? "added" : "left"
            //   } `,
            //   JSON.stringify(userList)
            // );
            if (updateType !== "ADD") {

              handleDisconnect();
            } else {
              // const current_users = JSON.stringify(userList);
              // * We can use current_users_list to build dynamic UI in a group call
              const remoteAudioStream = await zg.startPlayingStream(
                `audio_${userID}`
              );
              const remoteVideoStream = await zg.startPlayingStream(
                `video_${userID}`
              );

              // Get the audio tag.
              const remoteAudio = document.getElementById("remote-audio");
              const remoteVideo = document.getElementById("remote-video");
              // The local stream is a MediaStream object. You can render audio by assigning the local stream to the srcObject property of video or audio.

              remoteAudio.srcObject = remoteAudioStream;
              remoteVideo.srcObject = remoteVideoStream;
              remoteAudio.play();
              remoteVideo.play();
            }
          });

          // Callback for updates on the status of the streams in the room.
          zg.on("roomStreamUpdate",
            async (roomID, updateType, streamList, extendedData) => {
              if (updateType === "ADD") {
                // New stream added, start playing the stream.
                // console.log("ADD", roomID, updateType, streamList, extendedData);
                // * It would be quite useful to create and play multiple audio streams in a group call
              } else if (updateType === "DELETE") {
                // Stream deleted, stop playing the stream.
                // console.log("DELETE", roomID, updateType, streamList, extendedData);
                // * Can be used to drop audio streams (more useful in a group call)
              }
            }
          );

          zg.on("playerStateUpdate", (result) => {
            // Callback for updates on stream playing status.
            // ...
            // * Can be used to display realtime status of a remote audio stream (Connecting, connected & Disconnected)
          });

          zg.on("playQualityUpdate", (streamID, stats) => {
            // Callback for reporting stream playing quality.
            // * Can be used to display realtime quality of a remote audio stream
          });
        }
      })
      .catch((err) => {
        // console.log(err);
      });

    return () => {
      subscriptions.forEach((sub) => {
        webSocketService.unsubscribe(sub);
      });

      if (audioStreamRef.current) {
        const audioTracks = audioStreamRef.current.getTracks();
        audioTracks.forEach((track) => track.stop());
      }

      if (videoStreamRef.current) {
        const videoTracks = videoStreamRef.current.getTracks();
        videoTracks.forEach((track) => track.stop());
      }
    };
  }, []);

  return (
    <>
      <Dialog
        fullWidth
        maxWidth="lg"
        open={open}
        TransitionComponent={Transition}
        keepMounted
        onClose={handleDisconnect}
        aria-describedby="alert-dialog-slide-description"
      >
        <DialogContent sx={{ padding: 0, position: 'relative' }}>
          {userBusy && <Typography variant="h6">{"User Busy on another Call"}</Typography>}
          <Stack direction="row" p={1.5} justifyContent="center" alignItems="center">
            {/* Remote Video Stack */}
            <div style={{ position: 'relative', display: 'inline-block' }}>
              <video
                style={{
                  height: 700,
                  width: "100%",
                  borderRadius: '8px',
                  boxShadow: '0px 0px 10px rgba(0, 0, 0, 0.2)',
                  objectFit: "cover"
                }}
                id="remote-video"
                controls={false}
              />
              <audio id="remote-audio" controls={false} />
              <Typography
                variant="h6"
                sx={{
                  position: 'absolute',
                  bottom: '16px',
                  left: '10px',
                  color: 'white',
                  backgroundColor: 'rgba(0, 0, 0, 0.3)',
                  padding: '4px',
                  borderRadius: '8px',
                }}
              >
                {call_details?.from.firstName}
              </Typography>

              {/* Local Video positioned on top-right of the remote video */}
              <video
                style={{
                  position: 'absolute',
                  top: '10px',
                  right: '10px',
                  height: 150,
                  width: 200,
                  borderRadius: '8px',
                  boxShadow: '0px 0px 10px rgba(0, 0, 0, 0.3)',
                  zIndex: 1, // Ensure local video is on top
                }}
                id="local-video"
                controls={false}
              />
              <audio id="local-audio" controls={false} />
              <IconButton
                onClick={() => {
                  handleDisconnect();
                }}
                sx={{
                  position: 'absolute',
                  bottom: '2%',
                  left: '95%',
                  backgroundColor: '#f44336',
                  transition: "0.1s ease-in-out",
                  color: '#fff',
                  '&:hover': { backgroundColor: '#e53935', transform: 'scale3d(1.1, 1.1, 1.1)', },
                  // padding: 2,
                  zIndex: 2, // Ensure the button is above the video
                }}
              >
                <PhoneX size={24} />
              </IconButton>
            </div>
          </Stack>
        </DialogContent>
      </Dialog>
    </>
  );
};

export default CallDialog;